import {groupCases,groupCopy as copy} from './group-pieces-content.mjs';
import {createGroup,groupModel,previewGroup,applyGroup,undoGroup,compareGroup,groupExample} from './group-pieces-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=t=>`<p data-gp-read>${esc(t)}</p>`;
const count=(n,word)=>`${n} ${word}${n===1?'':'s'}`;
const button=(a,t,disabled=false)=>`<button type="button" data-gp-action="${a}"${disabled?' disabled':''}>${esc(t)}</button>`;
let visit=null,retire=()=>{},stopBinding=()=>{};
export function resetGroupPieces(){retire();stopBinding();visit=null;retire=()=>{};stopBinding=()=>{};}
function current(book,owner){if(!visit||visit.book!==book||visit.owner!==owner){retire();stopBinding();visit={book,owner,caseId:groupCases[0].id,cases:new Map(groupCases.map(c=>[c.id,createGroup(c.id)])),previews:new Map(),screen:'work',frame:0,caller:'work',grownUp:false};}return visit;}
function readout(m){return `Original: ${m.originalNumerator}/${m.originalDenominator}. Now: ${m.numerator}/${m.denominator}. ${m.denominator===1?'The whole is one piece now.':`Each current piece is 1/${m.denominator} of the whole.`}`;}
function previewText(m,q){if(m.denominator===1)return 'This whole is already one piece. Undo to explore earlier groups.';if(!q)return 'Choose a group size to preview it.';return `Whole: ${count(q.wholeGroups,'complete group')}, ${count(q.wholeRemainder,'current piece')} left. Colored part: ${count(q.coloredGroups,'complete group')}, ${count(q.coloredRemainder,'current colored piece')} left. ${q.fits?m.numerator===0?`There are no colored pieces, so none are left over. The whole makes ${count(q.wholeGroups,'complete group')}. Grouping by ${q.factor} will name the same amount: 0/${q.nextDenominator}.`:`Both counts form complete groups. Grouping by ${q.factor} will name the same amount ${q.nextNumerator}/${q.nextDenominator}.`:`Keep this as a preview. ${q.wholeRemainder&&q.coloredRemainder?'The whole and its colored part have pieces left over.':q.wholeRemainder?'The whole has pieces left over.':'The colored part has pieces left over.'} Try another group size.`}`;}
function strip(n,d,kind,id,q=null){const x=48,w=504,y=30,h=34,end=x+w*n/d;
 const marks=Array.from({length:d-1},(_,i)=>`<path class="gp-cut" d="M${x+w*(i+1)/d} ${y}v${h}"/>`).join('');
 let groups='';if(q){for(let i=0;i<q.wholeGroups;i++){const a=x+w*i*q.factor/d,b=x+w*(i+1)*q.factor/d;groups+=`<path data-gp-bracket="whole" d="M${a+1} 79v7H${b-1}v-7"/>`;}for(let i=0;i<q.coloredGroups;i++){const a=x+w*i*q.factor/d,b=x+w*(i+1)*q.factor/d;groups+=`<path data-gp-bracket="colored" d="M${a+1} 20v-7H${b-1}v7"/>`;}}
 const remainder=(role,r,total)=>r?`<rect data-gp-remainder="${role}" x="${x+w*(total-r)/d}" y="${role==='whole'?y+17:y}" width="${w*r/d}" height="17" fill="url(#${id}-${role})"/>`:'';
 return `<svg data-gp-diagram data-gp-strip="${kind}" viewBox="0 0 600 114" role="img" aria-label="${kind==='original'?'Original':kind==='different'?'Different amount':'Current'} ribbon: ${n} of ${d} equal pieces colored; the whole is 1."><defs><pattern id="${id}-whole" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M-2 2L2-2M0 8L8 0M6 10L10 6" class="gp-hatch-whole"/></pattern><pattern id="${id}-colored" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 0L8 8M-2 6L2 10M6-2L10 2" class="gp-hatch-colored"/></pattern></defs><rect data-gp-whole x="48" y="30" width="504" height="34"/><rect data-gp-shade="${kind==='original'?'original':'current'}" x="48" y="30" width="${w*n/d}" height="34"/>${q?remainder('whole',q.wholeRemainder,d)+remainder('colored',q.coloredRemainder,n):''}${marks}<rect class="gp-outline" x="48" y="30" width="504" height="34"/>${groups}<path class="gp-end" d="M48 26v43M552 26v43"/><path data-gp-flag="${kind==='original'?'original':'current'}" class="gp-flag" data-endpoint="${end}" d="M${end} 27V5l10 5-10 5"/><text x="48" y="108" text-anchor="middle">0</text><text x="552" y="108" text-anchor="middle">1</text></svg>`;}
function material(m,q=null,changed=false){return `<div class="gp-ribbons" data-gp-model data-numerator="${m.numerator}" data-denominator="${m.denominator}"><h3 data-gp-read>Original: ${m.originalNumerator}/${m.originalDenominator}</h3>${strip(m.originalNumerator,m.originalDenominator,'original','gp-original')}<h3 data-gp-read>${changed?'Different amount':'Now'}: ${m.numerator}/${m.denominator}</h3>${strip(m.numerator,m.denominator,changed?'different':'current','gp-current',q)}${p(readout(m))}${!changed?p('Same whole, same colored end. Fewer pieces are larger, not a smaller amount.'):p('Different amount: the original flag is at 2/3; the other flag is at 1/2. The whole is the same size.')}${q?p('Brass brackets collect complete groups. Lower rising hatches: whole pieces left. Upper falling hatches: colored pieces left. These roles can overlap.'):''}</div>`;}
function tools(v,m,q){return `<section class="gp-tools" aria-label="Grouping controls"><label>Group size<select data-gp-factor${m.denominator===1?' disabled':''}><option value="">Choose a group size</option>${m.groupSizes.map(g=>`<option value="${g}"${q?.factor===g?' selected':''}>${g}</option>`).join('')}</select></label><div class="gp-preview" data-gp-preview role="status">${p(previewText(m,q))}</div><div class="gp-actions">${button('apply','Group these pieces',!q?.fits)}${button('undo','Undo last grouping',!m.canUndo)}</div>${!m.canUndo?p('No grouping to undo yet.'):''}</section>`;}
function work(v,m,q){return `<label class="gp-case">Choose a ribbon<select data-gp-case>${groupCases.map(c=>`<option value="${c.id}"${v.caseId===c.id?' selected':''}>${esc(c.title)}</option>`).join('')}</select></label>${p(copy.story)}${p(copy.instruction)}<div class="gp-workbench">${material(m,q)}${tools(v,m,q)}</div><div class="gp-actions">${button('names','Check the names')}${button('example','Show me with 6/9')}</div>`;}
function names(v,m){const c=compareGroup(v.cases.get(v.caseId)),factor=m.originalPiecesPerCurrent;return `${material(m)}<div class="gp-explanation">${p(`${m.originalNumerator}/${m.originalDenominator} = ${m.numerator}/${m.denominator}. Each current piece contains ${count(factor,'original piece')}.`)}${p(factor===1?'Both counts still have their original names. Group complete equal pieces to divide both counts by the same factor.':`${m.originalNumerator} ÷ ${factor} = ${m.numerator} and ${m.originalDenominator} ÷ ${factor} = ${m.denominator}. Both counts were divided by the same factor.`)}${p(c.text)}</div><div class="gp-actions">${button('back','Back to my ribbon')}${button('example','Show me with 6/9')}</div>`;}
function example(v){const e=groupExample(v.frame);return `${p('These are separate example ribbons. Your ribbon and preview stay as you left them.')}${e.changedAmount?p('Subtract 3 from both counts: a different arithmetic claim.'):''}${material(e,e.preview,e.changedAmount)}${e.preview?p(previewText(e,e.preview)):''}<div class="gp-caption" role="status">${p(`Picture ${v.frame+1} of 6. ${e.text}`)}</div><nav class="gp-actions" aria-label="Example pictures">${button('previous','Previous',v.frame===0)}${button('next','Next',v.frame===5)}${button('back',v.caller==='compare'?'Back to the names':'Back to my ribbon')}</nav>`;}
export function groupPiecesPage(book,owner){const v=current(book,owner),m=groupModel(v.cases.get(v.caseId)),q=previewGroup(v.cases.get(v.caseId),v.previews.get(v.caseId));return `<section class="gp-page" data-gp-root><h2 id="gp-heading" tabindex="-1" data-gp-read>${v.screen==='work'?'Group Pieces':v.screen==='compare'?'Check the names':'Show me with 6/9'}</h2><div data-gp-view="${v.screen}"${v.screen==='example'?` data-gp-frame="${v.frame}"`:''}>${v.screen==='example'?example(v):v.screen==='compare'?names(v,m):work(v,m,q)}</div><div class="gp-actions">${hearButton('',v.screen==='example'?'Read this example':v.screen==='compare'?'Read these names':'Read this ribbon')}</div>${p(copy.visit)}<details data-gp-grownup${v.grownUp?' open':''}><summary>For grown-ups</summary>${p(copy.grownUp)}</details></section>`;}
// A removed, concealed or reparented control stays retired for this binding.
function bindingGuard(root,valid,stop){const controls=[root,...root.querySelectorAll('button,input,select,a,summary,details')].filter(n=>!n.closest?.('.speech-controls,drawn-howto')),chains=new Map(),retired=new WeakSet();let disconnected=false;
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};for(const n of controls)chains.set(n,chain(n));
 const audit=records=>{for(const r of records){if(r.target.closest?.('.speech-controls,drawn-howto'))continue;if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const disconnect=()=>{disconnected=true;observer.disconnect();};const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid()||retired.has(root)){stop();disconnect();}});observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return {disconnect,accepts(node){audit(observer.takeRecords());if(disconnected||!valid()||!root.isConnected||!root.contains(node)||node.disabled||retired.has(node))return false;const old=chains.get(node),now=chain(node);if(!old||old.length!==now.length||!old.every((n,i)=>n===now[i]))return false;for(let n=node;n?.nodeType===1;n=n.parentElement){const css=getComputedStyle(n);if(n.hidden||n.inert||n.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(n.tagName==='DETAILS'&&!n.open&&n!==node&&!n.querySelector(':scope>summary')?.contains(node))return false;}return node.getClientRects().length>0;}};
}
function visibleNarration(root){return [...root.querySelectorAll('[data-gp-read],label')].filter(n=>{for(let a=n;a;a=a.parentElement){const css=getComputedStyle(a);if(a.hidden||a.inert||a.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility)||a.tagName==='DETAILS'&&!a.open)return false;}return n.getClientRects().length>0;}).map(n=>n.matches('label')?[...n.childNodes].map(c=>c.nodeType===3?c.textContent:c.tagName==='SELECT'?c.selectedOptions[0]?.textContent:'').join(' '):n.textContent).map(s=>s.replace(/\s+/g,' ').trim()).join(' ');}
export function bindGroupPieces(book,ctx={}){retire();const root=document.querySelector('[data-gp-root]');if(!root||!visit)return;const v=visit,owner=typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,caseId=v.caseId,material=v.cases.get(caseId),bytes=JSON.stringify(material),preview=v.previews.get(caseId),screen=v.screen,frame=v.frame,caller=v.caller,parent=root.parentNode;
 const live=()=>root.isConnected&&root.parentNode===parent&&document.querySelector('[data-gp-root]')===root&&location.hash==='#workshop/common-cuts'&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook??book)===book&&(!ctx.isActive||ctx.isActive())&&(typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId)===owner&&visit===v&&v.book===book&&v.owner===owner&&v.caseId===caseId&&v.cases.get(caseId)===material&&JSON.stringify(material)===bytes&&v.previews.get(caseId)===preview&&v.screen===screen&&v.frame===frame&&v.caller===caller;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();},guard=bindingGuard(root,live,stop);retire=guard.disconnect;stopBinding=stop;
 for(const c of root.querySelectorAll('button,input,select,a,summary,details')){if(c.closest('.speech-controls,drawn-howto'))continue;for(const type of ['click','input','change','keydown'])c.addEventListener(type,e=>{if(!guard.accepts(c)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});}
 const redraw=(selector='#gp-heading')=>{guard.disconnect();ctx.render();let target=document.querySelector(selector);if(!target||target.disabled||!target.getClientRects().length)selector='#gp-heading';if(ctx.focus)ctx.focus(selector);else document.querySelector(selector)?.focus();};
 root.querySelector('[data-gp-grownup]')?.addEventListener('toggle',e=>{if(guard.accepts(e.target)&&v.grownUp!==e.target.open){v.grownUp=e.target.open;stop();}});
 root.addEventListener('click',e=>{const b=e.target.closest('[data-speak]');if(!b||!root.contains(b)||b.closest('.speech-controls,drawn-howto'))return;if(!guard.accepts(b)){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=visibleNarration(root);},{capture:true});
 root.querySelector('[data-gp-case]')?.addEventListener('change',e=>{if(!guard.accepts(e.target)||screen!=='work'||!v.cases.has(e.target.value)||caseId===e.target.value)return;stop();v.caseId=e.target.value;redraw('[data-gp-case]');});
 root.querySelector('[data-gp-factor]')?.addEventListener('change',e=>{if(!guard.accepts(e.target)||screen!=='work')return;const n=e.target.value===''?null:Number(e.target.value);if(n!==null&&!previewGroup(material,n))return;stop();v.previews.set(caseId,n);redraw('[data-gp-factor]');});
 root.querySelectorAll('[data-gp-action]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b))return;const a=b.dataset.gpAction;
 if(a==='example'&&screen!=='example'){stop();v.caller=screen;v.screen='example';v.frame=0;redraw();return;}
 if(a==='back'&&screen!=='work'){stop();v.screen=screen==='example'?caller:'work';redraw(`[data-gp-action="${screen==='example'?'example':'names'}"]`);return;}
 if(screen==='example'&&['previous','next'].includes(a)){const n=frame+(a==='next'?1:-1);if(!groupExample(n))return;stop();v.frame=n;redraw(`[data-gp-action="${n===5?'previous':n===0?'next':a}"]`);return;}
 if(screen!=='work')return;if(a==='names'){stop();v.screen='compare';redraw();return;}
 if(a!=='apply'&&a!=='undo')return;const next=a==='apply'?applyGroup(material,preview):undoGroup(material);if(!next)return;stop();v.cases.set(caseId,next);v.previews.set(caseId,null);redraw(groupModel(next).denominator===1?'[data-gp-action="undo"]':'[data-gp-factor]');
 }));
}
